SELECT LOGIN_STATUS_ID, ACCNT_ID, SESSION_ID, CURRENT_STATUS, PASSCODE_HASH, EXPIRES_AT, VERSION, IS_DELETED, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT FROM LOGIN_STATUS ORDER BY LOGIN_STATUS_ID, ACCNT_ID, SESSION_ID, CURRENT_STATUS, PASSCODE_HASH, EXPIRES_AT, VERSION, IS_DELETED, CREATED_BY, CREATED_AT, UPDATED_BY, UPDATED_AT;
